void Solver::restart() {
    // Reset LBD statistics
    fast_lbd_sum = 0;
    lbd_queue_size = 0;
    lbd_queue_pos = 0;

    // Backtrack to root level
    backtrack(0);

    // Aggressive rephasing strategy
    int phase_rand = rand() % 100;
    if (conflicts > 5000) {
        // For many conflicts, use completely random phases
        for (int i = 1; i <= vars; ++i) {
            saved[i] = (rand() & 1) ? 1 : -1;
        }
    } else if (phase_rand < 70) {
        // Mostly keep the best local phase
        for (int i = 1; i <= vars; ++i) {
            saved[i] = local_best[i];
        }
    } else {
        // Occasionally invert the best local phase
        for (int i = 1; i <= vars; ++i) {
            saved[i] = -local_best[i];
        }
    }

    // Reset variable activity increment to avoid excessive decay
    var_inc = 1.0;
}
